// Flatten the DataForB2B response and normalize fields (works with any response shape)
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const arr = Array.isArray(j) ? j : (j.results || j.profiles || j.people || j.data || j.items || ((j.linkedin_url || j.profile_url || j.public_identifier) ? [j] : []));
  for (const p of arr) {
    const url = p.linkedin_url || p.linkedinUrl || p.profile_url || p.profileUrl || p.url || (p.public_identifier ? `https://www.linkedin.com/in/${p.public_identifier}` : null);
    if (!url) continue;
    const fullName = p.full_name || p.name || `${p.first_name || ''} ${p.last_name || ''}`.trim();
    out.push({ json: {
      linkedin_url: url,
      full_name: fullName,
      first_name: p.first_name || p.firstName || fullName.split(' ')[0] || '',
      headline: p.headline || p.current_title || p.title || '',
      company: p.current_company || p.company || p.company_name || '',
      location: p.profile_location || p.location || p.profile_country || ''
    }});
  }
}
return out;
